CREATE TYPE "UserRole" AS ENUM ('reader', 'writer');

CREATE TABLE "User" (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email VARCHAR(200) NOT NULL UNIQUE,
  name TEXT NOT NULL DEFAULT E'O''Reilly\\notes',
  active BOOLEAN NOT NULL DEFAULT false,
  score INTEGER NOT NULL DEFAULT 0,
  nickname TEXT UNIQUE,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  token UUID NOT NULL DEFAULT gen_random_uuid(),
  role "UserRole" NOT NULL DEFAULT 'reader'
);
CREATE TABLE "Post" (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "userId" INTEGER NOT NULL,
  "reviewerId" INTEGER,
  title TEXT NOT NULL,
  CONSTRAINT post_author_fk FOREIGN KEY ("userId") REFERENCES "User" (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT post_reviewer_fk FOREIGN KEY ("reviewerId") REFERENCES "User" (id) ON DELETE SET NULL ON UPDATE SET NULL
);
CREATE INDEX post_author_idx ON "Post" ("userId");
CREATE INDEX post_reviewer_idx ON "Post" ("reviewerId");
CREATE TABLE "Profile" (
  "userId" INTEGER PRIMARY KEY,
  bio TEXT NOT NULL,
  CONSTRAINT profile_user_fk FOREIGN KEY ("userId") REFERENCES "User" (id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE "Space" (
  "tenantId" INTEGER NOT NULL,
  id INTEGER NOT NULL,
  name TEXT NOT NULL,
  PRIMARY KEY ("tenantId", id)
);
CREATE TABLE "Entry" (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tenantId" INTEGER NOT NULL,
  "spaceId" INTEGER NOT NULL,
  name TEXT NOT NULL,
  CONSTRAINT entry_space_fk FOREIGN KEY ("tenantId", "spaceId") REFERENCES "Space" ("tenantId", id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX entry_space_idx ON "Entry" ("tenantId", "spaceId");
CREATE TABLE "Tag" (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);
CREATE TABLE "PostTag" (
  "postId" INTEGER NOT NULL,
  "tagId" INTEGER NOT NULL,
  "addedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY ("postId", "tagId"),
  CONSTRAINT post_tag_post_fk FOREIGN KEY ("postId") REFERENCES "Post" (id) ON DELETE CASCADE,
  CONSTRAINT post_tag_tag_fk FOREIGN KEY ("tagId") REFERENCES "Tag" (id) ON DELETE CASCADE
);
CREATE INDEX post_tag_tag_idx ON "PostTag" ("tagId");
CREATE TABLE "Category" (
  "tenantId" INTEGER NOT NULL,
  id INTEGER NOT NULL,
  name TEXT NOT NULL,
  PRIMARY KEY ("tenantId", id)
);
CREATE TABLE "SpaceCategory" (
  "tenantId" INTEGER NOT NULL,
  "spaceId" INTEGER NOT NULL,
  "categoryId" INTEGER NOT NULL,
  PRIMARY KEY ("tenantId", "spaceId", "categoryId"),
  CONSTRAINT space_category_space_fk FOREIGN KEY ("tenantId", "spaceId") REFERENCES "Space" ("tenantId", id),
  CONSTRAINT space_category_category_fk FOREIGN KEY ("tenantId", "categoryId") REFERENCES "Category" ("tenantId", id)
);
CREATE INDEX space_category_category_idx ON "SpaceCategory" ("tenantId", "categoryId");
